try:
    print('>>> f = filter')
    print('>>> x = []')
    print('>>> y = range(0)')
    print('>>> f(x, y)')
    f = filter
    x = []
    y = range(0)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
